// TestEnvInt covers the B5 int-env-parsing logic: an empty value uses the
// default; a valid value overrides; a malformed value falls back to the default
// + logs (INV-env-defaults: startup never aborts on an enrich knob). The parser
// does not clamp — a negative passes through; enrich.NewQueue's withDefaults
// re-applies the §4.4 default for a non-positive value, so the pool cannot be
// accidentally disabled. That clamp is enrich's concern, asserted in enrich
// tests; this test pins the parser's own contract.
func TestEnvInt(t *testing.T) {
	const key = "MELLIFERA_TEST_ENV_INT"
	const def = 4
	for _, tc := range []struct {
		name string
		val  string
		want int
	}{
		{"empty_uses_default", "", def},
		{"valid_override", "8", 8},
		{"malformed_falls_back", "not-an-int", def},
		{"negative_passes_through_unclamped", "-1", -1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(key, tc.val)
			if got := envInt(key, def); got != tc.want {
				t.Errorf("envInt(%q=%q, def=%d) = %d, want %d", key, tc.val, def, got, tc.want)
			}
		})
	}
}

// TestOptionalPluginPathOverrides pins the two optional external-plugin path
// resolutions: an unset/empty MELLIFERA_JAV_PARSER / MELLIFERA_JAVINIZER falls
// back to the bin/ default, a set value overrides (the same envOr law as the
// eight built-in override sites).
func TestOptionalPluginPathOverrides(t *testing.T) {
	for _, tc := range []struct {
		name string
		key  string
		def  string
		val  string
		want string
	}{
		{"jav_parser_empty_uses_default", "MELLIFERA_JAV_PARSER", "bin/jav-parser", "", "bin/jav-parser"},
		{"jav_parser_env_overrides", "MELLIFERA_JAV_PARSER", "bin/jav-parser", "/opt/plugins/jav-parser", "/opt/plugins/jav-parser"},
		{"javinizer_empty_uses_default", "MELLIFERA_JAVINIZER", "bin/javinizer", "", "bin/javinizer"},
		{"javinizer_env_overrides", "MELLIFERA_JAVINIZER", "bin/javinizer", "/opt/plugins/javinizer", "/opt/plugins/javinizer"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(tc.key, tc.val)
			if got := envOr(tc.key, tc.def); got != tc.want {
				t.Errorf("envOr(%q=%q, def=%q) = %q, want %q", tc.key, tc.val, tc.def, got, tc.want)
			}
		})
	}
}

